CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS plants (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), code VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, description TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS functional_locations (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), plant_id UUID REFERENCES plants(id) ON DELETE SET NULL, parent_id UUID REFERENCES functional_locations(id) ON DELETE SET NULL, code VARCHAR(255) UNIQUE NOT NULL, name VARCHAR(255), description TEXT, level INTEGER NOT NULL DEFAULT 0, source VARCHAR(50) DEFAULT 'manual', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_fl_parent ON functional_locations(parent_id);
CREATE TABLE IF NOT EXISTS equipment (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), equipment_number VARCHAR(100) UNIQUE, functional_location_id UUID REFERENCES functional_locations(id) ON DELETE SET NULL, parent_equipment_id UUID REFERENCES equipment(id) ON DELETE SET NULL, name VARCHAR(255) NOT NULL, equipment_type VARCHAR(100), manufacturer VARCHAR(255), model VARCHAR(255), serial_number VARCHAR(255), installation_date DATE, commissioning_date DATE, criticality VARCHAR(20), status VARCHAR(50) NOT NULL DEFAULT 'UNKNOWN', metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_equipment_fl ON equipment(functional_location_id);
CREATE TABLE IF NOT EXISTS parameters (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), equipment_id UUID NOT NULL REFERENCES equipment(id) ON DELETE CASCADE, parameter_code VARCHAR(100) NOT NULL, name VARCHAR(255) NOT NULL, unit VARCHAR(50), data_type VARCHAR(30) DEFAULT 'numeric', normal_min DOUBLE PRECISION, normal_max DOUBLE PRECISION, warning_min DOUBLE PRECISION, warning_max DOUBLE PRECISION, critical_min DOUBLE PRECISION, critical_max DOUBLE PRECISION, source VARCHAR(50), created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(equipment_id, parameter_code));
CREATE TABLE IF NOT EXISTS condition_readings (id BIGSERIAL PRIMARY KEY, parameter_id UUID NOT NULL REFERENCES parameters(id) ON DELETE CASCADE, timestamp TIMESTAMPTZ NOT NULL, value DOUBLE PRECISION, quality VARCHAR(30) DEFAULT 'GOOD', source VARCHAR(50), metadata JSONB DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_condition_parameter_time ON condition_readings(parameter_id,timestamp DESC);
CREATE TABLE IF NOT EXISTS maintenance_events (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), equipment_id UUID REFERENCES equipment(id) ON DELETE SET NULL, sap_order_number VARCHAR(100), event_type VARCHAR(50), title VARCHAR(500), description TEXT, planned_start TIMESTAMPTZ, actual_start TIMESTAMPTZ, actual_end TIMESTAMPTZ, downtime_hours DOUBLE PRECISION, maintenance_team VARCHAR(255), cost DOUBLE PRECISION, source VARCHAR(50) DEFAULT 'manual', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS component_changes (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), equipment_id UUID NOT NULL REFERENCES equipment(id) ON DELETE CASCADE, changed_at TIMESTAMPTZ NOT NULL, component_name VARCHAR(255) NOT NULL, old_component VARCHAR(255), new_component VARCHAR(255), reason TEXT, performed_by VARCHAR(255), sap_order_number VARCHAR(100), running_hours DOUBLE PRECISION, source VARCHAR(50) DEFAULT 'manual', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_component_changes_equipment_time ON component_changes(equipment_id,changed_at DESC);
CREATE TABLE IF NOT EXISTS failures (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), equipment_id UUID REFERENCES equipment(id) ON DELETE SET NULL, notification_number VARCHAR(100), failure_start TIMESTAMPTZ, failure_end TIMESTAMPTZ, failure_mode VARCHAR(255), failure_cause VARCHAR(255), damage_code VARCHAR(100), cause_code VARCHAR(100), activity_code VARCHAR(100), description TEXT, breakdown BOOLEAN DEFAULT FALSE, downtime_hours DOUBLE PRECISION, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reliability_metrics (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), equipment_id UUID NOT NULL REFERENCES equipment(id) ON DELETE CASCADE, calculated_at TIMESTAMPTZ DEFAULT NOW(), mtbf_hours DOUBLE PRECISION, mttr_hours DOUBLE PRECISION, availability_percent DOUBLE PRECISION, failure_count INTEGER DEFAULT 0, downtime_hours DOUBLE PRECISION DEFAULT 0, reliability_score DOUBLE PRECISION, risk_score DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS documents (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), equipment_id UUID REFERENCES equipment(id) ON DELETE SET NULL, title VARCHAR(500) NOT NULL, document_type VARCHAR(100), source VARCHAR(255), file_path TEXT, content TEXT, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS document_chunks (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), document_id UUID NOT NULL REFERENCES documents(id) ON DELETE CASCADE, chunk_index INTEGER NOT NULL, content TEXT NOT NULL, embedding vector(768), metadata JSONB DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_document_chunks_embedding ON document_chunks USING hnsw (embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS import_jobs (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), filename VARCHAR(500) NOT NULL, import_type VARCHAR(100) NOT NULL, status VARCHAR(30) DEFAULT 'RECEIVED', rows_read INTEGER DEFAULT 0, rows_created INTEGER DEFAULT 0, rows_updated INTEGER DEFAULT 0, rows_skipped INTEGER DEFAULT 0, errors JSONB DEFAULT '[]', created_at TIMESTAMPTZ DEFAULT NOW(), completed_at TIMESTAMPTZ);
